use std::borrow::Cow;

fn clean(input: &str) -> Cow<str> {
    if input.contains("bad") {
        Cow::Owned(input.replace("bad", "good"))
    } else {
        Cow::Borrowed(input)
    }
}

fn main() {
    let a = clean("this is fine");
    let b = clean("bad day");
    println!("{}", a);
    println!("{}", b);
}

#[derive(Default)]
struct Config {
    host: String,
    port: u16,
}

impl Config {
    fn new() -> Self {
        Self::default()
    }

    fn host(mut self, host: &str) -> Self {
        self.host = host.to_string();
        self
    }

    fn port(mut self, port: u16) -> Self {
        self.port = port;
        self
    }
}

fn main() {
    let config = Config::new().host("localhost").port(8080);
    println!("{}:{}", config.host, config.port);
}

